import React, { createRef, FC, useEffect } from 'react'
import { debounce } from 'lodash'
import TextInput from '../../ui/form/TextInput'

import { tips } from '../locales'
import './styles.scss'

export interface AddressFilterInputProps {
  onChange: any
}

const AddressFilterInput:FC<AddressFilterInputProps> = ({
  onChange
}) => {
  const ref = createRef<HTMLDivElement>();
  const handleInputChange = debounce((val) => {
    onChange && onChange(val)
  }, 200)

  useEffect(() => {
    const { current } = ref
    current && (current.onclick = (e) => {
      e.stopPropagation()
    })

  })

  return (
    <div className="b3-address-search-container" ref={ ref }>
      <TextInput 
        onChange={ (e) => {
          handleInputChange(e.target.value)
        } }
        placeholder={ tips['b3.addresses.search'] }
      />
    </div>
  )
}

export default AddressFilterInput